package com.community.holiday.entity;

import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.time.LocalDate;

/**
 * 사이트 쉬는 날 한 줄 — V150 {@code site_holidays}(ID 는 DB 가 매긴다 — {@code GENERATED BY DEFAULT AS IDENTITY}). 출처 공공데이터·기본값·회사 휴무일, 같은 날 여러 줄
 * (같은 출처·날짜·이름은 하나, 회사 휴무일은 하루에 한 줄). 쉬는 날 판정은 토·일 + 이 표의 모든 날({@code BusinessDayCalendar}).
 */
@Entity
@Table(name = "site_holidays")
public class SiteHolidayEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private LocalDate holidayDate;
    private String name;

    @Enumerated(EnumType.STRING)
    private HolidaySource source;

    /** 대체공휴일 */
    private boolean substitute;
    /** 넣은 운영자(공공데이터·기본값·옮긴 줄은 null) */
    private Long createdBy;
    private Instant createdAt;
    private Instant updatedAt;

    protected SiteHolidayEntity() {
    }

    public static SiteHolidayEntity create(LocalDate date, String name, HolidaySource source, boolean substitute, Long createdBy, Instant now) {
        SiteHolidayEntity row = new SiteHolidayEntity();
        row.holidayDate = date;
        row.name = name;
        row.source = source;
        row.substitute = substitute;
        row.createdBy = createdBy;
        row.createdAt = now;
        row.updatedAt = now;
        return row;
    }

    public Long getId() {
        return id;
    }
}
